package com.yeyamo_mobile.api.feed_service.infrastructure.messaging;import java.time.Instant;import java.util.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.feed_service.application.FeedProjectionCommandService;import com.yeyamo_mobile.api.feed_service.domain.model.CultureContentLink;import com.yeyamo_mobile.api.feed_service.domain.model.FeedPost;
@Component public class FeedEventConsumer{private final ObjectMapper mapper;private final FeedProjectionCommandService commands;private final ProcessedEventRepository processed;public FeedEventConsumer(ObjectMapper m,FeedProjectionCommandService c,ProcessedEventRepository p){mapper=m;commands=c;processed=p;}
 @KafkaListener(topics="${yeyamo.kafka.topics.content-events:content.events}",groupId="${spring.kafka.consumer.group-id:feed-service}")@Transactional public void content(String raw)throws Exception{JsonNode e=valid(raw,"content-service");UUID id=UUID.fromString(e.get("eventId").asText());if(processed.existsById(id))return;JsonNode p=e.path("payload");UUID postId=UUID.fromString(required(p,"postId"));FeedPost post=new FeedPost(postId,required(p,"authorId"),text(p,"caption",null),text(p,"visibility","PRIVATE"),text(p,"status","DRAFT"),uuid(p,"catalogAssetId"),text(p,"referenceType","NONE"),text(p,"referenceId",null),uuids(p,"mediaIds"),strings(p,"hashtags"),text(p,"countryCode",null),text(p,"languageCode",null),instant(p,"publishedAt"),instant(e,"occurredAt"));commands.content(required(e,"eventType"),post,text(e,"correlationId",id.toString()));receipt(id,required(e,"eventType"));}
 @KafkaListener(id="feed-culture-events",topics="${yeyamo.kafka.topics.culture-events:culture.events}",groupId="${spring.kafka.consumer.group-id:feed-service}-culture")@Transactional public void culture(String raw)throws Exception{JsonNode e=valid(raw,"culture-service");UUID id=UUID.fromString(e.get("eventId").asText());if(processed.existsById(id))return;JsonNode p=e.path("payload");String type=required(p,"type");if("PROVERB".equals(type)||"RECIPE".equals(type)){UUID contentId=UUID.fromString(required(p,"contentId"));commands.culture(new CultureContentLink(contentId,type,text(p,"title",null),p.path("isActive").asBoolean(false)),text(e,"correlationId",id.toString()));}receipt(id,required(e,"eventType"));}
 @KafkaListener(topics="${yeyamo.kafka.topics.interaction-events:interaction.events}",groupId="${spring.kafka.consumer.group-id:feed-service}")@Transactional public void interaction(String raw)throws Exception{JsonNode e=valid(raw,"interaction-service");UUID id=UUID.fromString(e.get("eventId").asText());if(processed.existsById(id))return;String type=required(e,"eventType");JsonNode p=e.path("payload");UUID postId=uuid(p,"postId");if(postId==null){receipt(id,type);return;}String user=text(p,"userId",text(p,"authorId",text(e,"actorId",null)));commands.interaction(type,postId,user,text(e,"correlationId",id.toString()));receipt(id,type);}
 private JsonNode valid(String raw,String producer)throws Exception{JsonNode e=mapper.readTree(raw);required(e,"eventId");if(e.path("eventVersion").asInt(0)!=1)throw new IllegalArgumentException("Unsupported event version");if(!producer.equals(required(e,"producer")))throw new IllegalArgumentException("Unexpected producer");return e;}private void receipt(UUID id,String type){var r=new ProcessedEventEntity();r.setEventId(id);r.setEventType(type);r.setProcessedAt(Instant.now());processed.save(r);}private String required(JsonNode n,String f){String v=text(n,f,null);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f,String d){JsonNode v=n.get(f);return v==null||v.isNull()?d:v.asText();}private UUID uuid(JsonNode n,String f){String v=text(n,f,null);return v==null||v.isBlank()?null:UUID.fromString(v);}private Instant instant(JsonNode n,String f){String v=text(n,f,null);return v==null||v.isBlank()?null:Instant.parse(v);}private List<UUID>uuids(JsonNode n,String f){List<UUID>r=new ArrayList<>();JsonNode a=n.path(f);if(a.isArray())a.forEach(v->r.add(UUID.fromString(v.asText())));return r;}private List<String>strings(JsonNode n,String f){List<String>r=new ArrayList<>();JsonNode a=n.path(f);if(a.isArray())a.forEach(v->r.add(v.asText()));return r;}}
